"""Cleanup Script: Removes all test users, fake sales, fake slips, and fake keys generated by tests."""

import os
import re
import sys
import requests
import urllib3
urllib3.disable_warnings()

from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from dotenv import load_dotenv
load_dotenv(".env", override=True)

from bot_app.storage.kv import redis_set, redis_get, _kv_config
from bot_app.config import ADMIN_CHAT_IDS

KNOWN_TEST_IDS = {
    "111000111", "222000222", "555666000", "555666777", "555666779", "555666999",
    "999888777", "12345678", "4242424242", "8888111222", "888111222", "999333444",
    "12345001", "12345002", "12345003", "12345004", "777888999", "12345",
    "555", "777", "999", "1001", "1002", "2001", "2002", "555444333"
}

TEST_NAMES = {
    "Test", "test_customer", "test_buyer", "VIP Customer", "Loyal Customer",
    "Test Customer", "Test User", "Claimer 1", "Claimer 2", "Active User"
}

TEST_USERNAMES = {
    "admin_user", "testuser", "newbie_user", "active_user", "happy_customer",
    "test_customer", "test_user", "me", "carol"
}

def cleanup():
    url, token = _kv_config()
    print(f"Target DB: {url}")
    if not url or not token:
        print("ERROR: KV unconfigured!")
        return

    # 1. First fetch real Outline keys to know exactly who is real
    u1 = os.environ.get("OUTLINE_API_URL_1")
    real_outline_users = set()
    real_persistent_keys = {}
    real_key_mappings = {}
    real_user_plans = {}
    
    if u1:
        try:
            r = requests.get(f"{u1}/access-keys", verify=False, timeout=8)
            if r.status_code == 200:
                keys = r.json().get("accessKeys", [])
                for k in keys:
                    kid = str(k.get("id"))
                    name = k.get("name") or ""
                    access_url = k.get("accessUrl") or ""
                    limit_b = k.get("dataLimit", {}).get("bytes")

                    m_cid = re.search(r'\((\d{6,15})\)', name)
                    cid = m_cid.group(1) if m_cid else ""
                    if cid:
                        real_outline_users.add(str(cid))

                    m_date = re.search(r'\d{1,2}\.\d{1,2}\.(\d{4}|\d{2})', name)
                    exp_date = m_date.group(0) if m_date else "မသိရှိပါ"

                    clean_name = re.sub(r'\(\s*\d+\s*\)', '', name)
                    clean_name = re.sub(r'\d{1,2}\.\d{1,2}\.(\d{4}|\d{2})', '', clean_name).strip(' -–—·|')

                    uid = f"1_{kid}"
                    real_persistent_keys[uid] = {
                        "server": "1",
                        "key_id": kid,
                        "name": name,
                        "access_url": f"{access_url}#{name}" if name else access_url,
                        "limit_bytes": limit_b,
                        "expire_date": exp_date,
                        "order_id": "N/A",
                        "chat_id": cid
                    }
                    if name:
                        real_key_mappings[name.strip().lower()] = cid
                    if cid:
                        real_user_plans[str(cid)] = {
                            "plan_name": "Active Key",
                            "server": "1",
                            "key_id": kid,
                            "access_url": access_url,
                            "expiry": exp_date
                        }
        except Exception as e:
            print(f"Error fetching Outline keys: {e}")

    admin_ids = {str(a) for a in ADMIN_CHAT_IDS}
    valid_cids = real_outline_users | admin_ids

    # 2. Filter all_users & user_profiles
    all_users = redis_get("all_users") or []
    user_profiles = redis_get("user_profiles") or {}
    wallets = redis_get("user_wallets_data") or {}
    points = redis_get("points_data") or {}

    cleaned_users = []
    cleaned_profiles = {}
    cleaned_wallets = {}
    cleaned_points = {}
    dropped_users = []

    for uid in all_users:
        uid_str = str(uid)
        prof = user_profiles.get(uid_str, {})
        name = prof.get("name", "")
        username = prof.get("username", "")

        is_test = False
        if uid_str in KNOWN_TEST_IDS:
            is_test = True
        elif name in TEST_NAMES:
            is_test = True
        elif username in TEST_USERNAMES:
            is_test = True
        elif uid_str not in valid_cids and not name and not username:
            is_test = True

        if is_test and uid_str not in admin_ids:
            dropped_users.append((uid_str, name, username))
        else:
            cleaned_users.append(uid_str)
            if uid_str in user_profiles:
                cleaned_profiles[uid_str] = user_profiles[uid_str]
            cleaned_wallets[uid_str] = wallets.get(uid_str, 0)
            if uid_str in points:
                cleaned_points[uid_str] = points[uid_str]
            else:
                cleaned_points[uid_str] = {
                    "points": 0, "streak": 0, "last_claim_at": None,
                    "highest_streak": 0, "lifetime_claims": 0, "reminder_sent": False
                }

    # Ensure all real Outline users are in cleaned_users & cleaned_profiles
    for cid in real_outline_users:
        if cid not in cleaned_users:
            cleaned_users.append(cid)
        if cid not in cleaned_profiles:
            cleaned_profiles[cid] = {
                "chat_id": int(cid),
                "name": f"User {cid}",
                "username": "",
                "first_seen": "2026-10-18 00:00:00",
                "last_seen": "2026-10-18 00:00:00"
            }
        if cid not in cleaned_wallets:
            cleaned_wallets[cid] = 0
        if cid not in cleaned_points:
            cleaned_points[cid] = {
                "points": 0, "streak": 0, "last_claim_at": None,
                "highest_streak": 0, "lifetime_claims": 0, "reminder_sent": False
            }

    # Reset test wallets that had fake test money
    for uid in cleaned_users:
        if cleaned_wallets.get(uid, 0) in (5000, 10000, 4000, 7500):
            # Check if this user had fake test balance
            prof = cleaned_profiles.get(uid, {})
            if prof.get("username") in TEST_USERNAMES or prof.get("name") in TEST_NAMES:
                cleaned_wallets[uid] = 0

    cleaned_users = sorted(list(set(cleaned_users)))

    print(f"Removed {len(dropped_users)} test users:")
    for d in dropped_users:
        print(f"  - {d}")
    print(f"Preserved {len(cleaned_users)} real customers.")

    # 3. Clean sales_history (drop test sales with chat_ids in test list)
    sales = redis_get("sales_history") or []
    cleaned_sales = [s for s in sales if str(s.get("chat_id")) not in KNOWN_TEST_IDS and str(s.get("order_id", "")).startswith("#ORD-")]
    print(f"Cleaned sales: {len(sales)} -> {len(cleaned_sales)}")

    # 4. Clean admin_slips_data
    slips = redis_get("admin_slips_data") or {}
    cleaned_slips = {}
    if isinstance(slips, dict):
        for sid, s in slips.items():
            cid = str(s.get("chat_id") or "")
            if cid not in KNOWN_TEST_IDS and not str(sid).startswith("#PT"):
                cleaned_slips[sid] = s
    print(f"Cleaned slips: {len(slips)} -> {len(cleaned_slips)}")

    # 5. Clean admin_audit_logs
    audit_logs = redis_get("admin_audit_logs") or []
    cleaned_audit = [l for l in audit_logs if str(l.get("admin_id")) in admin_ids]
    print(f"Cleaned audit logs: {len(audit_logs)} -> {len(cleaned_audit)}")

    # 6. Clean persistent_keys_registry
    # Only keep keys that are on real Outline server
    print(f"Persistent keys: Restoring {len(real_persistent_keys)} real Outline keys.")

    # Commit all cleaned data to Upstash Redis
    redis_set("all_users", cleaned_users)
    redis_set("user_profiles", cleaned_profiles)
    redis_set("user_wallets_data", cleaned_wallets)
    redis_set("points_data", cleaned_points)
    redis_set("persistent_keys_registry", real_persistent_keys)
    redis_set("key_mappings", real_key_mappings)
    redis_set("user_plans", real_user_plans)
    redis_set("sales_history", cleaned_sales)
    redis_set("admin_slips_data", cleaned_slips)
    redis_set("admin_audit_logs", cleaned_audit)
    redis_set("user_purchases_data", {})

    print("\nSUCCESS: All test data purged and real customer records restored!")

if __name__ == "__main__":
    cleanup()
